contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 mintedAmount) public {
        require(mintedAmount <= type(uint256).max / 2);

        uint256 beforeBalance = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 beforeTotal = c.totalSupply(); if (__ESBMC_reverted()) return;

        c.mintToken(address(this), mintedAmount); if (__ESBMC_reverted()) return;

        uint256 afterBalance = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 afterTotal = c.totalSupply(); if (__ESBMC_reverted()) return;

        assert((afterBalance - beforeBalance) + (afterTotal - beforeTotal) == 2 * mintedAmount);
    }

    receive() external payable {}
}

