pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(uint256 mintedAmount) internal {
        vm.assume(mintedAmount <= type(uint256).max / 2);
        uint256 beforeBalance;
        try c.balanceOf(address(this)) returns (uint256 __r) { beforeBalance = __r; } catch { return; }
        uint256 beforeTotal;
        try c.totalSupply() returns (uint256 __r) { beforeTotal = __r; } catch { return; }
        try c.mintToken(address(this), mintedAmount) {} catch { return; }
        uint256 afterBalance;
        try c.balanceOf(address(this)) returns (uint256 __r) { afterBalance = __r; } catch { return; }
        uint256 afterTotal;
        try c.totalSupply() returns (uint256 __r) { afterTotal = __r; } catch { return; }
        assertTrue((afterBalance - beforeBalance) + (afterTotal - beforeTotal) == 2 * mintedAmount);
    }

    function testFuzz_run(uint256 mintedAmount) public {
        _run(mintedAmount);
    }

    receive() external payable {}
}
